fn argmin(a: Vec<i8>) -> usize {
    // Initialize the minimum value to the first element and its index to 0
    let mut min_value = a[0];
    let mut min_index = 0;

    // Iterate through the array starting from the first element
    for (index, &value) in a.iter().enumerate() {
        // If we find a new minimum, update min_value and min_index
        if value < min_value {
            min_value = value;
            min_index = index;
        }
    }

    // Return the index of the first occurrence of the smallest value
    min_index
}